{
  "title": "迷雾山洞",
  "scene": "山洞中弥漫着淡紫色的雾气，洞壁上隐约有着模糊的符号。你听到远处传来轻微的水流声，但听不清方向。洞壁上有一块明显的裂痕，裂缝中似乎有一束光芒透出。",
  "goal": "找到山洞尽头的秘密通道。",
  "clue": "洞壁上的模糊符号和裂缝中透出的光芒。",
  "choices": [
    {"id": "A", "text": "探索裂痕中的光芒", "outcome": "你沿着裂痕深入，发现一个机关，拉动后，光芒更亮，指引你向前。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "跟随水流声", "outcome": "你跟着水流声走了一段，却进入了一个死胡同，什么也没有找到。", "result": "fail", "next": "retry"},
    {"id": "C", "text": "研究洞壁上的符号", "outcome": "你仔细研究符号，发现它们似乎是由某种古老的语言书写的，但你无法完全理解，只记下了其中的几个关键词。", "result": "partial", "next": "next_level"}
  ]
}
